int largestComponent(std::vector<int> const& A, size_t N) {
   std::vector<bool> visited(N, false);
   int maxCount = 0;

   // Use a threshold for small graphs to avoid overhead of parallelism
   if (N < 100) {
      for (int i = 0; i < N; i += 1) {
         if (!visited[i]) {
            int count = 0;
            dfs(A, i, N, visited, count);
            maxCount = std::max(maxCount, count);
         }
      }
      return maxCount;
   }

   // Parallel DFS exploration of the graph
   #pragma omp parallel
   {
      int localMaxCount = 0;
      #pragma omp for
      for (int i = 0; i < N; i += 1) {
         if (!visited[i]) {
            int count = 0;
            dfs(A, i, N, visited, count);
            #pragma omp critical
            {
               localMaxCount = std::max(localMaxCount, count);
            }
         }
      }
      #pragma omp critical
      {
         maxCount = std::max(maxCount, localMaxCount);
      }
