void binsBy10Count(std::vector<double> const& x, std::array<size_t, 10> &bins) {
    const size_t size = x.size();
    size_t i = 0;
    __m256d increment = _mm256_set1_pd(1.0);

    // Process 4 elements at a time
    for (; i + 4 <= size; i += 4) {
        __m256d values = _mm256_loadu_pd(&x[i]);
        __m256d bin_indices = _mm256_floor_pd(values);
        bin_indices = _mm256_cvttpd_epi64(bin_indices);
        bin_indices = _mm256_slli_epi64(bin_indices, 3); // Multiply by 8
        __m256d bin_indices_d = _mm256_cvtepi64_pd(bin_indices);
        _mm256_storeu_pd(&bins[0], _mm256_add_pd(_mm256_loadu_pd(&bins[0]), increment));
        _mm256_storeu_pd(&bins[0], _mm256_add_pd(_mm256_loadu_pd(&bins[0]), bin_indices_d));
    }

    // Handle remaining elements
    for (; i < size; ++i) {
        size_t bin = x[i] / 10;
        bins[bin]++;
    }
}

