void binsBy10Count(std::vector<double> const& x, std::array<size_t, 10> &bins) {
    const size_t size = x.size();
    size_t i = 0;

    // Process 4 elements at a time using AVX2 SIMD instructions
    for (; i + 4 <= size; i += 4) {
        __m256d values = _mm256_loadu_pd(&x[i]);
        __m256d divisor = _mm256_set1_pd(10.0);
        __m256d bin_indices = _mm256_cvttps_epi32(_mm256_div_ps(_mm256_cvtpd_ps(values), divisor));
        __m256d increments = _mm256_set1_pd(1.0);
        __m256d bin_counts = _mm256_cvtepi32_pd(bin_indices);
        bin_counts = _mm256_add_pd(bin_counts, increments);

        // Horizontal addition to get bin counts for 4 elements
        __m128d bin_counts_lo = _mm256_extractf128_pd(bin_counts, 0);
        __m128d bin_counts_hi = _mm256_extractf128_pd(bin_counts, 1);
        __m128d sum_lo = _mm_add_pd(_mm_cvtpd_ps(bin_counts_lo), _mm_setzero_ps());
        __m128d sum_hi = _mm_add_pd(_mm_cvtpd_ps(bin_counts_hi), _mm_setzero_ps());
        __m128d sum = _mm_add_pd(sum_lo, sum_hi);
        __m128d sums = _mm_cvtps_pd(sum);

        // Update bin counts
        for (int j = 0; j < 4; ++j) {
            bins[(int)_mm_cvtsd_f64(sums, j)]++;
        }
    }

    // Handle remaining elements
    for (; i < size; i++) {
        bins[static_cast<int>(x[i] / 10)]++;
    }
}

