*/
void firstLetterCounts(std::vector<std::string> const& s, std::array<size_t, 26> &bins) {
   for (int i = 0; i < s.size(); i += 1) {
      const char c = s[i][0];
      const int index = c - 'a';
      bins[index] += 1;
   }
}

