#pragma once

#include <vector>
#include <algorithm>
#include <omp.h>

void partialMinimums(std::vector<float> &x) {
    if (x.empty()) return;

    float *min_values = new float[x.size()];
    min_values[0] = x[0];

    // Parallel computation of minimum values using OpenMP
    #pragma omp parallel for
    for (size_t i = 1; i < x.size(); i++) {
        min_values[i] = std::min(min_values[i - 1], x[i]);
    }

    // Copy the minimum values back to the original vector
    for (size_t i = 0; i < x.size(); i++) {
        x[i] = min_values[i];
    }

    delete[] min_values;
