#include <vector>
#include <omp.h>

void prefixSum(std::vector<double> const& x, std::vector<double> &output) {
    size_t n = x.size();
    if (n == 0) return;
    output[0] = x[0];

    // Use sequential computation for small sizes
    if (n < 1000) {
        for (size_t i = 1; i < n; ++i) {
            output[i] = output[i - 1] + x[i];
        }
        return;
    }

    // Parallel computation for larger sizes
    #pragma omp parallel
    {
        double local_sum[16] = {0}; // Assuming 16 threads for optimization
        #pragma omp for
        for (size_t i = 0; i < n; ++i) {
            size_t tid = omp_get_thread_num();
            local_sum[tid] += x[i];
        }
        #pragma omp critical
        {
            for (size_t j = 0; j < omp_get_num_threads(); ++j) {
                output[j] += local_sum[j]; // Accumulate to the main output
            }
        }
    }

    // Final adjustments to the output
    for (size_t i = 1; i < n; ++i) {
        output[i] += output[i - 1];
    }
}

