#include <immintrin.h>

void oneMinusInverse(std::vector<double> &x) {
    const int size = x.size();
    if (size < 1000) { // Threshold for small sizes
        for (int i = 0; i < size; ++i) {
            x[i] = 1.0 - 1.0 / x[i];
        }
        return;
    }

    // Use SIMD for larger sizes
    #pragma omp parallel for
    for (int i = 0; i < size; i += 4) {
        __m256d x_data = _mm256_loadu_pd(&x[i]);
        __m256d one = _mm256_set1_pd(1.0);
        __m256d inv = _mm256_div_pd(one, x_data);
        __m256d result = _mm256_sub_pd(one, inv);
        _mm256_storeu_pd(&x[i], result);
    }

    // Handle any remaining elements
    for (int i = (size / 4) * 4; i < size; ++i) {
        x[i] = 1.0 - 1.0 / x[i];
    }
}

