    // Fill the matrix with the values from A
    for (const auto& element : A) {
        matrix[element.row][element.column] = element.value;
    }

    x.assign(N, 0.0);

    // Perform Gaussian elimination with partial pivoting and loop unrolling
    for (size_t i = 0; i < N; i += 2) {
        // Find pivot for the current row
        double maxEl = std::abs(matrix[i][i]);
        size_t maxRow = i;
        if (i + 1 < N) {
            double absVal = std::abs(matrix[i + 1][i]);
            if (absVal > maxEl) {
                maxEl = absVal;
                maxRow = i + 1;
            }
        }

        // Swap maximum row with current row (column by column)
        if (maxRow!= i) {
            for (size_t k = 0; k < N; ++k) {
                std::swap(matrix[maxRow][k], matrix[i][k]);
            }
            std::swap(b_copy[maxRow], b_copy[i]);
        }

        // Eliminate below the current row
        for (size_t k = i + 2; k < N; ++k) {
            double c = -matrix[k][i] / matrix[i][i];
            matrix[k][i] = 0.0; // Ensure this element is zeroed
            b_copy[k] += c * b_copy[i];
            for (size_t j = i + 1; j < N; ++j) {
                matrix[k][j] += c * matrix[i][j];
            }
        }
