void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
   // Create a sparse matrix representation using a vector of vectors
   std::vector<std::vector<std::pair<size_t, double>>> matrix(N);

   // Fill the matrix with the values from A
   for (const auto& element : A) {
      matrix[element.row].emplace_back(element.column, element.value);
   }

   // Gaussian elimination with partial pivoting
   for (size_t i = 0; i < N; ++i) {
      // Find pivot
      size_t pivotRow = i;
      double maxPivot = std::abs(matrix[i][0].second);
      for (size_t k = i + 1; k < N; ++k) {
         if (std::abs(matrix[k][0].second) > maxPivot) {
            maxPivot = std::abs(matrix[k][0].second);
            pivotRow = k;
         }
      }

      // Swap rows directly in the matrix to reduce overhead
      if (pivotRow!= i) {
         std::swap(matrix[i], matrix[pivotRow]);
         std::swap(b[i], b[pivotRow]);
      }

      // Eliminate below the main diagonal
      for (size_t j = i + 1; j < N; ++j) {
         double factor = -matrix[j][0].second / matrix[i][0].second;
         b[j] += factor * b[i];
         // Update the sparse matrix element in place
         for (auto& entry : matrix[j]) {
            if (entry.first == i) {
               entry.second = 0.0; // Mark elimination
               break;
            }
            entry.second += factor * matrix[i][0].second;
         }
      }
   }

   // Back substitution to solve for x
   for (size_t i = N; i-- > 0;) {
      x[i] = b[i];
      for (size_t j = 0; j < matrix[i].size(); ++j) {
         if (matrix[i][j].first!= i) {
            x[i] -= matrix[i][j].second * x[matrix[i][j].first];
         }
      }
      x[i] /= matrix[i][0].second;
   }
}

