int smallestOdd(std::vector<int> const& x) {
    int minOdd = std::numeric_limits<int>::max();
    for (int num : x) {
        if (num % 2!= 0) {
            minOdd = std::min(minOdd, num);
        }
    }
    return minOdd!= std::numeric_limits<int>::max()? minOdd : -1;
}

