int smallestOdd(std::vector<int> const& x) {
    if (x.empty()) return std::numeric_limits<int>::max();

    int min_odd = std::numeric_limits<int>::max();

    #pragma omp parallel
    {
        int local_min_odd = std::numeric_limits<int>::max();
        #pragma omp for
        for (size_t i = 0; i < x.size(); ++i) {
            if (x[i] % 2 == 1 && x[i] < local_min_odd) {
                local_min_odd = x[i];
            }
        }
        #pragma omp critical
        {
            if (local_min_odd < min_odd) {
                min_odd = local_min_odd;
            }
        }
    }
    return min_odd;
}

