    size_t size = x.size();
    double result = 1.0;
    size_t i = 0;

    // Process 4 elements at a time using AVX2
    for (; i + 4 <= size; i += 4) {
        __m256d x_vec = _mm256_loadu_pd(&x[i]);
        __m256d inv_vec = _mm256_div_pd(_mm256_set1_pd(1.0), x_vec);
        __m256d result_vec = _mm256_loadu_pd(&result);
        result_vec = _mm256_mul_pd(result_vec, _mm256_blendv_pd(x_vec, inv_vec, _mm256_set1_epi64x(0xAAAAAAAAAAAAAAAA)));
