#define M_PI 3.14159265358979323846
#endif

void fft(std::vector<std::complex<double>> const& x, std::vector<std::complex<double>> &output) {
    output = x;

    // Compute the FFT using SIMD instructions
    unsigned int N = output.size();
    if (N <= 0) return;

    // Bit reversal
    for (unsigned int i = 0; i < N; i++) {
        unsigned int rev = i;
        rev = ((rev & 0xaaaaaaaa) >> 1) | ((rev & 0x55555555) << 1);
        rev = ((rev & 0xcccccccc) >> 2) | ((rev & 0x33333333) << 2);
        rev = ((rev & 0xf0f0f0f0) >> 4) | ((rev & 0x0f0f0f0f) << 4);
        rev = ((rev & 0xff00ff00) >> 8) | ((rev & 0x00ff00ff) << 8);
        rev = (rev >> 16) | (rev << 16);
        rev >>= 32 - (unsigned int)(std::log2(N));
        if (i < rev) {
            std::swap(output[i], output[rev]);
        }
    }

    // Compute the FFT
    for (unsigned int size = 1; size < N; size <<= 1) {
        double angle = -2 * M_PI / (2 * size);
        std::complex<double> w(cos(angle), sin(angle));
        for (unsigned int i = 0; i < N; i += 2 * size) {
            std::complex<double> wn(1, 0);
            for (unsigned int j = 0; j < size; j++) {
                std::complex<double> t = wn * output[i + j + size];
                std::complex<double> u = output[i + j];
                output[i + j] = u + t;
                output[i + j + size] = u - t;
                wn *= w;
            }
        }
    }
}

