    unsigned int N = x.size();
    output.resize(N);
    if (N == 0) return;
    if (N == 1) {
        output[0] = x[0];
        return;
    }

    // Create bit reversed copy of x
    std::vector<std::complex<double>> brev_x(N);
    for (unsigned int i = 0; i < N; i++) {
        unsigned int rev = 0;
        for (unsigned int j = 0; j < sizeof(unsigned int) * 8; j++) {
            rev = (rev << 1) | (i & (1 << j))? 1 : 0;
        }
        brev_x[i] = x[rev];
    }

    // Compute FFT
    std::vector<std::complex<double>> temp(N);
    unsigned int levels = static_cast<unsigned int>(std::log2(N));
    unsigned int size = 1;
    for (unsigned int s = 0; s <= levels; s++) {
        unsigned int step = size << 1;
        unsigned int half = size;
        for (unsigned int i = 0; i < N; i += step) {
            std::complex<double> w(1, 0);
            std::complex<double> wn(std::cos(2 * M_PI / step), -std::sin(2 * M_PI / step));
