#endif

void fft(std::vector<std::complex<double>> const& x, std::vector<std::complex<double>> &output) {
    unsigned int N = x.size();
    output.resize(N);
    if (N == 0) return;
    if (N == 1) {
        output[0] = x[0];
        return;
    }

    // Bit reversal
    for (unsigned int i = 0; i < N; i++) {
        unsigned int rev = 0;
        for (unsigned int j = 0; j < sizeof(unsigned int) * 8; j++) {
            rev = (rev << 1) | (i & 1);
            i >>= 1;
        }
        output[rev] = x[i];
    }

    // Cooley-Tukey FFT
    unsigned int levels = (unsigned int)std::log2(N);
    unsigned int size = 1;
    for (unsigned int level = 0; level < levels; level++) {
        unsigned int step = size << 1;
        double angle = -2.0 * M_PI / size;
        std::complex<double> w(1.0, 0.0);
        std::complex<double> wm(std::cos(angle), std::sin(angle));
        #pragma omp parallel for
        for (unsigned int pos = 0; pos < size; pos++) {
            std::complex<double> t = w * output[pos + size];
            std::complex<double> u = output[pos];
            output[pos] = u + t;
            output[pos + size] = u - t;
        }
        w = wm;
        for (unsigned int stepPos = size; stepPos < N; stepPos += step) {
            std::complex<double> tw = w * output[stepPos];
            #pragma omp simd
            for (unsigned int i = 0; i < size; i++) {
                std::complex<double> t = output[stepPos + i];
                std::complex<double> u = output[stepPos - size + i];
                output[stepPos + i] = u + tw;
                output[stepPos - size + i] = u - tw;
                tw = w * t;
            }
            w *= wm;
        }
        size <<= 1;
    }
}

