    for (unsigned int i = 0; i < N; i++) {
        output[i] = x[i];
    }

    // Bit reversal permutation
    unsigned int m = (unsigned int)std::log2(N);
    for (unsigned int a = 0; a < N; a++) {
        unsigned int b = a;
        // Reverse bits
        b = (((b & 0xaaaaaaaa) >> 1) | ((b & 0x55555555) << 1));
        b = (((b & 0xcccccccc) >> 2) | ((b & 0x33333333) << 2));
        b = (((b & 0xf0f0f0f0) >> 4) | ((b & 0x0f0f0f0f) << 4));
        b = (((b & 0xff00ff00) >> 8) | ((b & 0x00ff00ff) << 8));
        b = ((b >> 16) | (b << 16)) >> (32 - m);
        if (b > a) {
            std::complex<double> t = output[a];
            output[a] = output[b];
            output[b] = t;
        }
    }

    // Compute FFT
    for (unsigned int k = 1; k < N; k <<= 1) {
        std::complex<double> wk = std::polar(1.0, -2.0 * M_PI / (2 * k));
        for (unsigned int j = 0; j < N; j += 2 * k) {
            std::complex<double> w = 1.0;
            for (unsigned int i = 0; i < k; i++) {
                std::complex<double> t = w * output[j + k + i];
                std::complex<double> u = output[j + i];
                output[j + i] = u + t;
                output[j + k + i] = u - t;
                w *= wk;
            }
        }
    }
}

