void fft_step(std::vector<std::complex<double>> &x, int step, int start) {
    int n = x.size();
    if (step < n) {
        for (int i = start; i < n; i += step * 2) {
            for (int j = 0; j < step; ++j) {
                std::complex<double> t = x[i + j + step] * std::exp(std::complex<double>(0, -2.0 * M_PI * j / step));
                x[i + j + step] = x[i + j] - t;
