void fft(std::vector<std::complex<double>> &x) {
    int n = x.size();
    if (n <= 1) return;

    // bit reverse
    for (int i = 0; i < n; ++i) {
        int j = i;
        int k = 0;
        while (j > 0) {
            k = (k << 1) | (j & 1);
            j >>= 1;
        }
        if (i < k) std::swap(x[i], x[k]);
    }

    // fft
    #pragma omp parallel
    {
        #pragma omp for
        for (int i = 0; i < n; i += 2) {
            std::complex<double> t = x[i + 1];
            x[i + 1] = x[i] - t;
            x[i] += t;
        }

        #pragma omp for
        for (int i = 4; i < n; i += 4) {
            std::complex<double> t1 = x[i + 1];
            std::complex<double> t2 = x[i + 2];
            std::complex<double> t3 = x[i + 3];
            x[i + 1] = x[i] - t1;
            x[i + 2] = x[i + 2] - t2;
            x[i + 3] = x[i + 3] - t3;
            x[i] += t1;
            x[i + 2] += t2;
            x[i + 3] += t3;
        }
    }

    // fft steps
    for (int step = 2; step < n; step *= 2) {
        #pragma omp parallel for
        for (int start = 0; start < n; start += step * 2) {
            fft_step(x, step, start);
        }
    }
}

