void convexHull(std::vector<Point> const& points, std::vector<Point> &hull) {
    if (points.size() < 3) {
        hull = points;
        return;
    }

    // Step 1: Find the lowest point
    auto it = std::min_element(points.begin(), points.end(), [](const Point& a, const Point& b) {
        return (a.y < b.y) || (a.y == b.y && a.x < b.x);
    });
    Point lowest = *it;

    // Step 2: Sort the points based on their polar angle with the lowest point
    std::vector<Point> sortedPoints;
    for (const auto& p : points) {
        if (p!= lowest) {
            sortedPoints.push_back(p);
        }
    }
    std::sort(sortedPoints.begin(), sortedPoints.end(), [&lowest](const Point& a, const Point& b) {
        double angleA = std::atan2(a.y - lowest.y, a.x - lowest.x);
        double angleB = std::atan2(b.y - lowest.y, b.x - lowest.x);
        return angleA < angleB;
    });

    // Step 3: Compute the convex hull
    std::vector<Point> convexHull;
    convexHull.push_back(lowest);    // Start with the lowest point
    convexHull.push_back(sortedPoints[0]);    // Add the next point
    convexHull.push_back(sortedPoints[1]);    // Add the second point

    for (size_t i = 2; i < sortedPoints.size(); ++i) {
        while (convexHull.size() > 2 && 
               (sortedPoints[i].y - convexHull[convexHull.size() - 1].y) * (convexHull[convexHull.size() - 1].x - convexHull[convexHull.size() - 2].x) > 
               (sortedPoints[i].x - convexHull[convexHull.size() - 1].x) * (convexHull[convexHull.size() - 1].y - convexHull[convexHull.size() - 2].y)) {
            convexHull.pop_back();
        }
        convexHull.push_back(sortedPoints[i]);
    }

    hull = convexHull;
}

