void convexHull(std::vector<Point> const& points, std::vector<Point> &hull) {
    // The polygon needs to have at least three points
    if (points.size() < 3)   {
        hull = points;
        return;
    }

    // Find the point with the lowest y-coordinate, or if there are multiple, the one with the lowest x-coordinate
    auto minPointIt = std::min_element(points.begin(), points.end(), [](Point const& a, Point const& b) {
        return a.y < b.y || (a.y == b.y && a.x < b.x);
    });
    Point minPoint = *minPointIt;

    // Sort the points based on their angle with the minimum point
    std::vector<Point> sortedPoints(points.size());
    std::copy(points.begin(), points.end(), sortedPoints.begin());
    std::sort(sortedPoints.begin(), sortedPoints.end(), [minPoint](Point const& a, Point const& b) {
        if (a == minPoint) return true;
        if (b == minPoint) return false;
        double angleA = std::atan2(a.y - minPoint.y, a.x - minPoint.x);
        double angleB = std::atan2(b.y - minPoint.y, b.x - minPoint.x);
        return angleA < angleB;
    });

    // Use Graham's scan to find the convex hull
    std::vector<Point> convexHull;
    convexHull.reserve(points.size());
    convexHull.push_back(minPoint);
    convexHull.push_back(sortedPoints[0]);
    convexHull.push_back(sortedPoints[1]);

    for (size_t i = 2; i < sortedPoints.size(); ++i) {
        while (convexHull.size() > 2
               && (sortedPoints[i].y - convexHull[convexHull.size() - 1].y) * (convexHull[convexHull.size() - 1].x - convexHull[convexHull.size() - 2].x)
                   > (sortedPoints[i].x - convexHull[convexHull.size() - 1].x) * (convexHull[convexHull.size() - 1].y - convexHull[convexHull.size() - 2].y)) {
            convexHull.pop_back();
        }
        convexHull.push_back(sortedPoints[i]);
