#include <vector>
#include <algorithm>
#include <omp.h>

void convexHull(std::vector<Point> const& points, std::vector<Point> &hull) {
    // The polygon needs to have at least three points
    if (points.size() < 3) {
        hull = points;
        return;
    }

    // Sort the points to ensure a consistent order
    std::vector<Point> pointsSorted(points);
    std::sort(pointsSorted.begin(), pointsSorted.end(), [](Point const& a, Point const& b) {
        return a.x < b.x || (a.x == b.x && a.y < b.y);
    });

    // A lambda function to calculate the cross product
    auto CrossProduct = [](Point const& a, Point const& b, Point const& c) {
        return (c.x - a.x) * (b.y - a.y) - (c.y - a.y) * (b.x - a.x) > 0;
    };

    // Use two stacks to store the upper and lower hulls
    std::vector<Point> upperHull;
    std::vector<Point> lowerHull;
    upperHull.reserve(pointsSorted.size());
    lowerHull.reserve(pointsSorted.size());

    // Fill the upper and lower hulls in parallel
    #pragma omp parallel
    {
        // Local stacks for each thread
        std::vector<Point> localUpperHull;
        std::vector<Point> localLowerHull;

        #pragma omp for
        for (size_t i = 0; i < pointsSorted.size(); ++i) {
            // Fill upper hull
            while (localUpperHull.size() > 1 &&!CrossProduct(localUpperHull[localUpperHull.size() - 2], localUpperHull[localUpperHull.size() - 1], pointsSorted[i])) {
                localUpperHull.pop_back();
            }
            localUpperHull.push_back(pointsSorted[i]);

            // Fill lower hull
            while (localLowerHull.size() > 1 &&!CrossProduct(localLowerHull[localLowerHull.size() - 2], localLowerHull[localLowerHull.size() - 1], pointsSorted[pointsSorted.size() - i - 1])) {
                localLowerHull.pop_back();
            }
            localLowerHull.push_back(pointsSorted[pointsSorted.size() - i - 1]);
        }

        // Combine local results into global hulls
        #pragma omp critical
        {
            upperHull.insert(upperHull.end(), localUpperHull.begin(), localUpperHull.end());
            lowerHull.insert(lowerHull.end(), localLowerHull.begin(), localLowerHull.end());
        }
    }

    // Combine the upper and lower hulls into the final convex hull
    hull.reserve(upperHull.size() + lowerHull.size() - 2);
    hull.insert(hull.end(), upperHull.begin(), upperHull.end());
    // Remove the first and last points (which are duplicates)
    hull.erase(hull.begin());
    hull.pop_back();
    hull.insert(hull.end(), lowerHull.rbegin() + 1, lowerHull.rend() - 1);
}

