    // Step 3: Compute the convex hull
    hull.reserve(sortedPoints.size() + 1);
    hull.push_back(lowest);
    for (size_t i = 0; i < sortedPoints.size(); ++i) {
        while (hull.size() > 1 && (sortedPoints[i].x - hull[hull.size() - 2].x) * (hull[hull.size() - 1].y - hull[hull.size() - 2].y) > (sortedPoints[i].y - hull[hull.size() - 2].y) * (hull[hull.size() - 1].x - hull[hull.size() - 2].x)) {
