    if (points.size() < 3) {
        hull = points;
        return;
    }

    // Step 1: Find the lowest point
    auto it = std::min_element(points.begin(), points.end(), [](Point const& a, Point const& b) {
        return a.y < b.y || (a.y == b.y && a.x < b.x);
    });
    Point lowest = *it;

    // Step 2: Sort the points based on their polar angle with the lowest point
    std::vector<Point> sortedPoints(points.size());
    std::copy(points.begin(), points.end(), sortedPoints.begin());
    std::sort(sortedPoints.begin(), sortedPoints.end(), [&lowest](Point const& a, Point const& b) {
        if (a == lowest) return true;
        if (b == lowest) return false;
        double angleA = std::atan2(a.y - lowest.y, a.x - lowest.x);
        double angleB = std::atan2(b.y - lowest.y, b.x - lowest.x);
        return angleA < angleB || (angleA == angleB && (a.x - lowest.x) * (a.x - lowest.x) + (a.y - lowest.y) * (a.y - lowest.y) < (b.x - lowest.x) * (b.x - lowest.x) + (b.y - lowest.y) * (b.y - lowest.y));
