        double angleB = std::atan2(b.y - lowest.y, b.x - lowest.x);
        return angleA < angleB || (angleA == angleB && (a.x - lowest.x) * (a.x - lowest.x) + (a.y - lowest.y) * (a.y - lowest.y) < (b.x - lowest.x) * (b.x - lowest.x) + (b.y - lowest.y) * (b.y - lowest.y));
