            }
            if (input[i * N + j] == 1) {
                if (sum < 2) {
                    output[i * N + j] = 0;
                } else if (sum == 2 || sum == 3) {
                    output[i * N + j] = 1;
                } else {
                    output[i * N + j] = 0;
                }
            } else {
                if (sum == 3) {
                    output[i * N + j] = 1;
                } else {
                    output[i * N + j] = 0;
