void gameOfLife(std::vector<int> const& input, std::vector<int> &output, size_t N) {
    // Create a temporary output array to store the new state of each cell
    std::vector<int> temp_output(N * N);

    #pragma omp parallel for
    for (size_t i = 0; i < N; i++) {
        for (size_t j = 0; j < N; j++) {
            int sum = 0;
            int index = i * N + j;

            // Check the cell's direct neighbors
            if (i > 0) {
                sum += input[(i - 1) * N + j];
            }
            if (i < N - 1) {
                sum += input[(i + 1) * N + j];
            }
            if (j > 0) {
                sum += input[i * N + (j - 1)];
            }
            if (j < N - 1) {
                sum += input[i * N + (j + 1)];
            }

            // Check the cell's diagonal neighbors
            if (i > 0 && j > 0) {
                sum += input[(i - 1) * N + (j - 1)];
            }
            if (i > 0 && j < N - 1) {
                sum += input[(i - 1) * N + (j + 1)];
            }
            if (i < N - 1 && j > 0) {
                sum += input[(i + 1) * N + (j - 1)];
            }
            if (i < N - 1 && j < N - 1) {
                sum += input[(i + 1) * N + (j + 1)];
            }

            // Apply the rules to determine the new state of the cell
            int currentState = input[index];
            if (currentState == 1) {
                if (sum < 2 || sum > 3) {
                    temp_output[index] = 0;
                } else {
                    temp_output[index] = 1;
                }
            } else {
                if (sum == 3) {
                    temp_output[index] = 1;
                } else {
                    temp_output[index] = 0;
                }
            }
        }
    }

    // Copy the temporary output to the final output array
