/* Solve the linear system Ax=b for x.
   A is an NxN matrix in row-major. x and b have N elements.
   Example:

   input: A=[[1,4,2], [1,2,3], [2,1,3]] b=[11, 11, 13]
   output: x=[3, 1, 2]
*/
void solveLinearSystem(std::vector<double> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
   // Gaussian elimination with partial pivoting
   for (size_t i = 0; i < N - 1; i++) {
      // Find the pivot element
      size_t pivotIndex = i;
      double pivotValue = A[i * N + i];
      for (size_t j = i + 1; j < N; j++) {
         if (A[j * N + i] > pivotValue) {
            pivotIndex = j;
            pivotValue = A[j * N + i];
         }
      }

      // Swap rows if necessary
      if (pivotIndex!= i) {
         for (size_t k = 0; k < N; k++) {
            std::swap(A[i * N + k], A[pivotIndex * N + k]);
         }
         std::swap(b[i], b[pivotIndex]);
      }

      // Eliminate the elements below the pivot
      for (size_t j = i + 1; j < N; j++) {
         double factor = A[j * N + i] / A[i * N + i];
         for (size_t k = i; k < N; k++) {
            A[j * N + k] -= factor * A[i * N + k];
         }
         b[j] -= factor * b[i];
      }
   }

   // Back substitution
   for (int i = N - 1; i >= 0; i--) {
      double sum = 0;
      for (size_t j = i + 1; j < N; j++) {
         sum += A[i * N + j] * x[j];
      }
      x[i] = (b[i] - sum) / A[i * N + i];
   }
}

