void sortComplexByMagnitude(std::vector<std::complex<double>> &x) {
    const int size = x.size();
    if (size < 16) { // Threshold for switching to insertion sort
        insertionSort(x, 0, size);
        return;
    }

    // Use parallel sorting for larger sizes
    #pragma omp parallel
    {
        #pragma omp single
        {
            // Divide the vector into segments and sort each segment in parallel
            const int segmentSize = (size / omp_get_num_threads()) + 1;
            std::vector<std::vector<std::complex<double>>> segments(omp_get_num_threads());
            for (int i = 0; i < omp_get_num_threads(); ++i) {
                int start = i * segmentSize;
                int end = std::min(start + segmentSize, size);
                segments[i] = std::vector<std::complex<double>>(x.begin() + start, x.begin() + end);
            }
            #pragma omp parallel for
            for (int i = 0; i < omp_get_num_threads(); ++i) {
                insertionSort(segments[i], 0, segments[i].size());
            }
            // Merge sorted segments into the original vector
            int index = 0;
            for (const auto & segment : segments) {
                std::copy(segment.begin(), segment.end(), x.begin() + index);
                index += segment.size();
            }
        }
    }
}

