#include <omp.h>

void sortIgnoreZero(std::vector<int> &x) {
    // Count non-zero elements
    size_t nonZeroCount = 0;
    #pragma omp parallel for reduction(+:nonZeroCount)
    for (size_t i = 0; i < x.size(); i += 1) {
        if (x[i]!= 0) {
            nonZeroCount++;
        }
    }

    // Create a temporary vector to hold non-zero elements
    std::vector<int> nonZeroElements;
    nonZeroElements.reserve(nonZeroCount);
    #pragma omp parallel for
    for (size_t i = 0; i < x.size(); i += 1) {
        if (x[i]!= 0) {
            nonZeroElements.push_back(x[i]);
        }
    }

    // Sort the non-zero elements
    std::sort(nonZeroElements.begin(), nonZeroElements.end());

    // Replace non-zero elements in the original vector
    size_t nonZeroIndex = 0;
    #pragma omp parallel for
    for (size_t i = 0; i < x.size(); i += 1) {
        if (x[i]!= 0) {
            x[i] = nonZeroElements[nonZeroIndex++];
        }
    }
}

