int findKthSmallest(std::vector<int> const& x, int k) {
    if (x.empty()) return -1; // handle empty vector case
    if (k <= 0 || k > static_cast<int>(x.size())) return -1; // handle invalid k case

    std::vector<int> x_copy = x;
    int n = x_copy.size();
    int const chunk_size = 16; // size of chunks for parallel processing
    int num_chunks = (n + chunk_size - 1) / chunk_size; // calculate number of chunks

    // Use insertion sort for small vectors to avoid overhead of parallel sort
    if (n < 16) {
        std::sort(x_copy.begin(), x_copy.end());
        return x_copy[k - 1];
    }

    // Use OpenMP for parallel sorting of chunks
    #pragma omp parallel for
    for (int i = 0; i < num_chunks; ++i) {
        int start = i * chunk_size;
        int end = std::min(start + chunk_size, n);
        std::sort(x_copy.begin() + start, x_copy.begin() + end);
    }

    // Merge sorted chunks
    std::vector<int> temp(n);
    int step = 1;
    while (step < n) {
