#include <vector>
#include <omp.h>

int findKthSmallest(std::vector<int> const& x, int k) {
    std::vector<int> x_copy = x;
    int n = x_copy.size();
    if (n < 1000) { // Use insertion sort for small n
        std::sort(x_copy.begin(), x_copy.end());
        return x_copy[k-1];
    }
    // Use median of three pivot selection for partitioning
    int mid = n / 2;
    if (x_copy[0] > x_copy[mid]) std::swap(x_copy[0], x_copy[mid]);
    if (x_copy[0] > x_copy[n-1]) std::swap(x_copy[0], x_copy[n-1]);
    if (x_copy[mid] > x_copy[n-1]) std::swap(x_copy[mid], x_copy[n-1]);
    std::swap(x_copy[mid], x_copy[n-2]); // Place pivot
    int pivot = x_copy[n-2];
    int left = 0;
    int right = n - 1;
    int i = 0;
    while (i <= right) {
        if (x_copy[i] < pivot) {
            std::swap(x_copy[i], x_copy[left]);
            ++left;
            ++i;
        } else if (x_copy[i] > pivot) {
            std::swap(x_copy[i], x_copy[right]);
            --right;
        } else {
            ++i;
