    if (k <= left) {
        return findKthSmallest(std::vector<int>(x_copy.begin(), x_copy.begin() + left), k);
    } else if (k > right) {
        return findKthSmallest(std::vector<int>(x_copy.begin() + right + 1, x_copy.end()), k - right - 1);
    }
    return x_copy[left];
}

