bool contains(std::vector<int> const& x, int target) {
    if (x.empty()) return false;
    if (x.size() < 1000) { // Threshold for small vectors
        return std::find(x.begin(), x.end(), target)!= x.end();
    }

    bool found = false;
    #pragma omp parallel
    {
        bool local_found = false;
        #pragma omp for
        for (size_t i = 0; i < x.size(); ++i) {
            if (x[i] == target) {
                local_found = true;
            }
        }
        #pragma omp atomic
        found |= local_found;
    }
    return found;
}

